// Why Code: revisa qué herramientas usó el asistente en este mensaje y arma un solo texto de aviso.
const pasos = $json.intermediateSteps ?? [];
const datos = $('Datos del mensaje').item.json;
const link = `https://wa.me/${datos.telefono}`;
const lineas = [];
for (const p of pasos) {
  const tool = p.action?.tool;
  const inp = p.action?.toolInput ?? {};
  if (tool === 'reservar_turno') {
    const ini = DateTime.fromISO(inp.inicio).setZone('America/Argentina/Buenos_Aires').setLocale('es');
    lineas.push(`📅 Nueva reserva (esperando seña)\n${inp.servicio} — ${inp.nombre_cliente}\n${ini.toFormat("cccc d 'de' LLLL, HH:mm")} hs`);
  }
  if (tool === 'avisar_a_la_terapeuta') {
    lineas.push(`🙋 ${datos.nombre || 'Una persona'} necesita que le escribas vos\nMotivo: ${inp.motivo ?? ''}\nSu último mensaje: "${datos.texto}"`);
  }
}
if (!lineas.length) return null;
return { json: { aviso: lineas.join('\n\n') + `\n\nChat: ${link}` } };
